package io.github.jesterportfolio.hearth.survival.platform;

import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.io.*;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.event.entity.*;import org.bukkit.inventory.*;
import io.github.jesterportfolio.hearth.survival.*;import io.github.jesterportfolio.hearth.survival.rpg.*;import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.inventory.*;import io.github.jesterportfolio.hearth.survival.economy.NativeTransactions;
import net.kyori.adventure.text.Component;

/** 장비·판매·월드 교체·설정 이전을 기존 경제 수명주기에 연결하는 선택 모듈. */
public final class PlatformRuntime implements Listener,AutoCloseable {
    public final RpgRuntime rpg;public final org.bukkit.plugin.java.JavaPlugin plugin;public final Executor owner;
    public final PlatformIo files=new PlatformIo();public final PlatformArchiveStore archives;public final PlatformStore store;public final ResourceGenerations resources;public final JobRuntime jobs;public final ConfigurationChanges changes;public final PlatformMetrics metrics=new PlatformMetrics();public final PlatformMenus menus;
    private final PaperInventoryCodec codec=new PaperInventoryCodec();private final UpgradeEngine upgrades=new UpgradeEngine();private final java.security.SecureRandom random=new java.security.SecureRandom();
    private final Path file;private PlatformSettings settings;private long generation;private volatile boolean closed;private boolean opened,maintenance,configBusy,restartRequired;private ConfigurationReview configReview=new ConfigurationReview(List.of(),List.of("NOT_LOADED"));private int lastSale,saleCursor;private int vaultPending;
    private Map<UUID,PlatformStore.Preference> preferences=new HashMap<>();private final Set<UUID> preferenceBusy=new HashSet<>(),sales=new HashSet<>(),dirty=new LinkedHashSet<>();
    private final Map<String,EconomyContent.Key> markets=new TreeMap<>();private final org.bukkit.scheduler.BukkitTask pulse;
    public PlatformRuntime(RpgRuntime rpg)throws Exception{this.rpg=rpg;plugin=rpg.plugin;owner=rpg.owner;file=plugin.getDataFolder().toPath().toAbsolutePath().resolve("platform.properties");if(!Files.exists(file))try(var in=Objects.requireNonNull(plugin.getResource("platform.properties"))){Files.copy(in,file);}settings=read();validate(settings);store=new PlatformStore(rpg.runtime.economy().database(),rpg.runtime.economy().store,rpg.runtime.economy().settings.realm());archives=new PlatformArchiveStore(rpg.runtime.economy().database(),rpg.runtime.economy().store,rpg.runtime.economy().settings.realm());resources=new ResourceGenerations(this);jobs=new JobRuntime(this);changes=new ConfigurationChanges(plugin.getDataFolder().toPath());menus=new PlatformMenus(this);Bukkit.getPluginManager().registerEvents(this,plugin);pulse=Bukkit.getScheduler().runTaskTimer(plugin,this::tick,20,20);Objects.requireNonNull(plugin.getCommand("hearthplatform")).setExecutor((sender,c,label,args)->{try{menus.command(sender,args);}catch(Exception error){sender.sendMessage(Component.text("플랫폼 요청 거부: "+error.getMessage()));}return true;});}
    public PlatformSettings settings(){return settings;}public long generation(){return generation;}public boolean configurationBusy(){return configBusy;}public boolean maintenance(){return maintenance;}public boolean ready(){return opened&&!closed&&!maintenance;}
    public PlatformGate gate(){return new PlatformGate(opened,closed,maintenance,configBusy,resources.busy(),jobs.busy(),rpg.runtime.economy().transactions.settled(),rpg.ready(),rpg.runtime.phase()==SurvivalRuntime.Phase.READY,rpg.runtime.economy().phase()==io.github.jesterportfolio.hearth.survival.economy.SurvivalEconomy.Phase.READY);}
    public boolean jobsAllowed(){return gate().dispatch();}
    public boolean available(Player p){return ready()&&!configBusy&&rpg.available(p)&&!resources.busy()&&!preferenceBusy.contains(p.getUniqueId())&&!rpg.runtime.economy().peers.busy(p.getUniqueId())&&worldAllowed(p.getWorld())&&rpg.runtime.admission().allowed(p,p.getLocation());}
    public boolean worldAllowed(World w){return !maintenance&&resources.allowed(w);}
    public CompletionStage<Void> open(){return store.preferences().thenComposeAsync(values->{preferences=new HashMap<>(values);rpg.aura.statPolicy(settings.stacking(),settings.statCap());return reviewConfig().thenComposeAsync(review->{maintenance=!review.clear()||vaultPending>0;return resources.open().thenComposeAsync(v->jobs.open(),owner);},owner);},owner).thenRunAsync(()->{opened=true;if(rpg.enchants!=null)rpg.enchants.deliveryObserver((player,action,producer,items)->mark(player));plugin.getLogger().info("HEARTH_PLATFORM_READY maintenance="+maintenance);},owner);}
    private PlatformSettings read()throws Exception{if(!file.equals(file.toRealPath())||Files.size(file)>131072)throw new IOException("PLATFORM_CONFIG_PATH");var p=new Properties();try(var in=Files.newBufferedReader(file)){p.load(in);}return PlatformSettings.parse(p);}
    private void validate(PlatformSettings next){markets.clear();for(var merchant:rpg.runtime.economy().merchants.all())for(String good:merchant.shop().goods())markets.putIfAbsent(good,new EconomyContent.Key(merchant.shop().region(),good));if(!markets.keySet().containsAll(next.goods())||next.materials().keySet().stream().anyMatch(m->Material.matchMaterial(m)==null))throw new IllegalArgumentException("PLATFORM_UNKNOWN_GOOD_OR_MATERIAL");}
    public void reload()throws Exception{if(maintenance)throw new IllegalStateException("CONFIG_RECOVERY_REQUIRED");if(configBusy||resources.busy()||jobs.busy()||!sales.isEmpty()||!rpg.runtime.economy().transactions.settled())throw new IllegalStateException("PLATFORM_BUSY");var next=read();validate(next);if(!next.jobs().equals(settings.jobs()))throw new IllegalStateException("JOBS_REQUIRE_CONFIG_CHANGE");settings=next;generation++;rpg.aura.statPolicy(next.stacking(),next.statCap());for(var p:Bukkit.getOnlinePlayers())rpg.aura.reconcile(p,rpg.abilityAllowed(p));}
    public PlatformStore.Preference preference(UUID player){return preferences.getOrDefault(player,new PlatformStore.Preference(false,Set.of(),-1));}
    public CompletionStage<Void> preference(Player p,boolean enabled,Set<String> goods){if(!available(p)||!settings.goods().containsAll(goods)||!preferenceBusy.add(p.getUniqueId()))return CompletableFuture.failedFuture(new IllegalStateException("AUTOSELL_PREFERENCE_BUSY"));var before=preference(p.getUniqueId());return store.preference(rpg.runtime.economy().context(p),new PlatformStore.Preference(enabled,goods,before.revision()),before.revision()).thenAcceptAsync(saved->{preferences.put(p.getUniqueId(),saved);mark(p);},owner).whenCompleteAsync((v,e)->preferenceBusy.remove(p.getUniqueId()),owner);}
    public void mark(Player player){if(dirty.size()<1024)dirty.add(player.getUniqueId());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void pickup(EntityPickupItemEvent e){if(e.getEntity() instanceof Player p)mark(p);}
    @EventHandler public void quit(PlayerQuitEvent e){dirty.remove(e.getPlayer().getUniqueId());}
    private void tick(){if(!ready())return;long start=System.nanoTime();try{jobs.pulse();if(settings.autosell()&&Bukkit.getCurrentTick()-lastSale>=settings.interval()){lastSale=Bukkit.getCurrentTick();var online=new ArrayList<>(Bukkit.getOnlinePlayers());for(int n=0;n<Math.min(64,online.size());n++){var player=online.get(Math.floorMod(saleCursor++,online.size()));if(preference(player.getUniqueId()).enabled())mark(player);}int work=0;for(UUID id:List.copyOf(dirty)){if(++work>8)break;dirty.remove(id);var player=Bukkit.getPlayer(id);if(player!=null)autosell(player);}}}finally{metrics.record("pulse",System.nanoTime()-start,false);}}
    public void autosell(Player p){if(!available(p)||!settings.autosell()||!p.getItemOnCursor().isEmpty()||p.getOpenInventory().getTopInventory().getType()!=org.bukkit.event.inventory.InventoryType.CRAFTING||sales.contains(p.getUniqueId()))return;var prefs=preference(p.getUniqueId());if(!prefs.enabled())return;var before=rpg.runtime.economy().capture(p);var allowed=new HashSet<>(prefs.goods());allowed.retainAll(settings.goods());var selection=AutoSalePlanner.select(codec.decode(before),rpg.runtime.economy().content.goods(),allowed,settings.quantity());if(selection.isEmpty())return;final String good=selection.get().good();final int count=selection.get().quantity();long start=System.nanoTime();long version=generation;Object session=rpg.runtime.sessionToken(p);var context=rpg.runtime.economy().context(p);sales.add(p.getUniqueId());rpg.runtime.economy().store.offer(context,markets.get(good)).thenComposeAsync(offer->{if(version!=generation||!available(p)||!rpg.runtime.current(p,session)||!preference(p.getUniqueId()).equals(prefs)||!rpg.runtime.economy().capture(p).equals(before))throw new IllegalStateException("AUTOSELL_STALE");UUID request=UUID.randomUUID();return rpg.runtime.economy().transactions.begin(request,"SHOP",List.of(rpg.runtime.economy().port(p)),rpg.runtime.economy().ledger.shop(context,offer,count,false,request,EconomyStore.Probe.NONE));},owner).whenCompleteAsync((v,e)->{sales.remove(p.getUniqueId());metrics.record("autosell",System.nanoTime()-start,e!=null);},owner);}
    public CompletionStage<?> upgrade(Player p,UUID request,int slot,int protection,long version,InventoryPayload before){if(!available(p)||version!=generation||!rpg.runtime.economy().capture(p).equals(before))return CompletableFuture.failedFuture(new IllegalStateException("UPGRADE_STALE"));var plan=upgrades.plan(codec.decode(before),slot,protection,settings,random.nextDouble());var after=codec.encode(plan.after());Object token=rpg.runtime.sessionToken(p);var context=rpg.runtime.economy().context(p);long start=System.nanoTime();return rpg.runtime.economy().store.account(context).thenComposeAsync(account->{if(!available(p)||version!=generation||!rpg.runtime.current(p,token)||!rpg.runtime.economy().capture(p).equals(before))throw new IllegalStateException("UPGRADE_STALE");String fingerprint="upgrade/"+slot+"/"+protection+"/"+version+"/"+plan.level()+"/"+plan.chance()+"/"+plan.roll()+"/"+plan.cost()+"/"+EnchantStore.hash(before)+"/"+EnchantStore.hash(after);var intent=new EnchantStore.Intent(request,fingerprint,"UPGRADE","hearth:equipment_upgrade",before,after,plan.outcome(),plan.chance(),plan.roll(),plan.cost(),account.inventory().revision());return rpg.runtime.economy().transactions.begin(request,"UPGRADE",List.of(rpg.runtime.economy().port(p)),(original,valid)->{if(!original.get(p.getUniqueId()).equals(before))throw new IllegalStateException("UPGRADE_STALE");return new EnchantStore(rpg.runtime.economy().database(),rpg.runtime.economy().store).execute(context,intent,valid).thenApply(receipt->new NativeTransactions.Result(Map.of(p.getUniqueId(),receipt.after()==null?before:receipt.after()),receipt,receipt.replay()));});},owner).whenCompleteAsync((v,e)->{metrics.record("upgrade",System.nanoTime()-start,e!=null);if(rpg.runtime.current(p,token)){rpg.aura.reconcile(p,rpg.abilityAllowed(p));p.sendMessage(Component.text(e==null?"강화 결과: "+plan.outcome():"강화 거부/보류 · 원본과 요청 기록을 확인하세요."));}},owner);}
    public CompletionStage<?> protection(Player p){if(!available(p))return CompletableFuture.failedFuture(new IllegalStateException("PLATFORM_NOT_READY"));var before=rpg.runtime.economy().capture(p);var values=codec.decode(before);io.github.jesterportfolio.hearth.survival.enchants.EnchantOperations.insert(values,EquipmentData.protection());var after=codec.encode(values);UUID request=UUID.randomUUID();Object token=rpg.runtime.sessionToken(p);var context=rpg.runtime.economy().context(p);return rpg.runtime.economy().store.account(context).thenComposeAsync(account->{if(!available(p)||!rpg.runtime.current(p,token)||!rpg.runtime.economy().capture(p).equals(before))throw new IllegalStateException("PLATFORM_STALE");return rpg.runtime.economy().transactions.begin(request,"UPGRADE",List.of(rpg.runtime.economy().port(p)),(original,valid)->new EnchantStore(rpg.runtime.economy().database(),rpg.runtime.economy().store).execute(context,new EnchantStore.Intent(request,"upgrade-protection/"+EnchantStore.hash(before),"GRANT","hearth:upgrade_protection",before,after,"GRANTED",1,0,0,account.inventory().revision()),valid).thenApply(receipt->new NativeTransactions.Result(Map.of(p.getUniqueId(),receipt.after()==null?before:receipt.after()),receipt,receipt.replay())));},owner);}
    public void validateCandidate(String name,byte[] before,byte[] after)throws Exception{if(name.equals("platform.properties")){var props=new Properties();props.load(new ByteArrayInputStream(after));var next=PlatformSettings.parse(props);validate(next);return;}if(name.equals("rpg-policy.properties")){var props=new Properties();props.load(new ByteArrayInputStream(after));RpgPolicy.parse(props);return;}if(name.equals("rpg-content.properties")){var old=new Properties();old.load(new ByteArrayInputStream(before));var next=new Properties();next.load(new ByteArrayInputStream(after));for(String key:old.stringPropertyNames())if(key.startsWith("extra.")||key.equals("allow-create-extras"))if(!Objects.equals(old.getProperty(key),next.getProperty(key)))throw new IllegalArgumentException("CONFIG_WORLD_IDENTITY_IMMUTABLE");ContentValidation.validate(old,next,id->{try{return rpg.aura.stat(id)!=null;}catch(Exception missing){return false;}},id->rpg.aura.api.getGlobalRegistry().getTrait(dev.aurelium.auraskills.api.registry.NamespacedId.fromString(id))!=null,id->Material.matchMaterial(id)!=null);return;}if(name.startsWith("enchants/")&&rpg.enchants!=null){if(name.endsWith("/operations.yml"))rpg.enchants.validateOperationCandidate(new String(after,java.nio.charset.StandardCharsets.UTF_8));else rpg.enchants.catalog.validateCandidate(name.substring(9),new String(after,java.nio.charset.StandardCharsets.UTF_8));return;}throw new IllegalArgumentException("CONFIG_ADAPTER_REQUIRED");}
    public ConfigurationReview configReview(){return configReview;}
    public CompletionStage<ConfigurationReview> reviewConfig(){return store.configs().thenCombine(archives.vaults(),(rows,vaults)->Map.entry(rows,vaults)).thenCompose(pair->files.submit(()->Map.entry(ConfigurationReview.read(changes,pair.getKey()),pair.getValue()))).thenApplyAsync(pair->{if(!closed){configReview=pair.getKey();vaultPending=(int)pair.getValue().stream().filter(v->Set.of("PREPARED","RESTORING").contains(v.state())).count();}return pair.getKey();},owner);}
    private static ConfigurationChanges.Validator frozen(ConfigurationChanges.Input input){return (name,a,b)->{if(!Arrays.equals(a,input.before())||!Arrays.equals(b,input.after()))throw new IOException("CONFIG_EXTERNAL_CHANGE");};}
    public CompletionStage<ConfigurationChanges.Plan> stageConfig(String name,String candidate){return files.submit(()->changes.candidate(name,candidate)).thenApplyAsync(input->{try{if(closed)throw new IllegalStateException("CONFIG_CLOSED");validateCandidate(name,input.before(),input.after());return input;}catch(Exception e){throw new CompletionException(e);}},owner).thenCompose(input->files.submit(()->changes.stage(name,candidate,frozen(input))));}
    public CompletionStage<ConfigurationChanges.Detail> inspectConfig(UUID id){return files.submit(()->changes.inspect(id));}
    private CompletionStage<Void> writeConfig(ConfigurationChanges.Plan plan,boolean rollback,boolean publish){return files.submit(()->changes.input(plan,rollback)).thenApplyAsync(input->{try{if(closed)throw new IllegalStateException("CONFIG_CLOSED");validateCandidate(plan.name(),input.before(),input.after());return input;}catch(Exception e){throw new CompletionException(e);}},owner).thenCompose(input->files.submit(()->{if(closed)throw new IllegalStateException("CONFIG_CLOSED");if(publish)changes.publish(plan,rollback,frozen(input));else changes.begin(plan,rollback,frozen(input));return (Void)null;}));}
    private boolean configIdle(){return gate().configuration()&&sales.isEmpty()&&preferenceBusy.isEmpty();}
    private void loadLive(String name)throws Exception{if(name.equals("platform.properties")){var next=read();validate(next);settings=next;rpg.aura.statPolicy(next.stacking(),next.statCap());}else if(name.startsWith("enchants/"))rpg.enchants.reload();generation++;}
    private void settleConfiguration(boolean hold){maintenance=hold||vaultPending>0;for(var player:Bukkit.getOnlinePlayers())rpg.aura.reconcile(player,rpg.abilityAllowed(player));}
    /** 보류가 모두 확정됐을 때만 live 설정을 재검증한다. 재시작 요구/다른 시스템 HOLD는 해제하지 않는다. */
    public CompletionStage<Void> recoverConfig(){
        if(!configIdle())return CompletableFuture.failedFuture(new IllegalStateException("CONFIG_BUSY"));configBusy=true;
        return reviewConfig().thenAcceptAsync(review->{if(!review.clear())throw new IllegalStateException("CONFIG_PENDING_REVIEW");if(vaultPending>0)throw new IllegalStateException("VAULT_PENDING_REVIEW");if(restartRequired)throw new IllegalStateException("CONFIG_RESTART_REQUIRED");try{loadLive("platform.properties");if(rpg.enchants!=null)loadLive("enchants/operations.yml");}catch(Exception e){throw new CompletionException(e);}},owner).thenComposeAsync(v->jobs.configure(settings.jobs()),owner).thenRunAsync(()->settleConfiguration(false),owner).whenCompleteAsync((v,e)->{configBusy=false;if(e!=null)maintenance=true;},owner);
    }
    private static final class ConfigRefusal extends IllegalArgumentException{ConfigRefusal(){super("CONFIG_ARCHIVED_OR_UNKNOWN");}}
    private static boolean harmless(Throwable error){while(error instanceof CompletionException||error instanceof ExecutionException)error=error.getCause();return error instanceof ConfigRefusal;}
    public CompletionStage<Void> apply(UUID id,boolean rollback){
        if(!configIdle())return CompletableFuture.failedFuture(new IllegalStateException("CONFIG_BUSY"));
        configBusy=true;long start=System.nanoTime();
        return files.submit(()->{if(!changes.hot(id))throw new ConfigRefusal();return changes.plan(id);}).thenComposeAsync(plan->{
            if(closed||plan.restart()&&!Bukkit.getOnlinePlayers().isEmpty())throw new IllegalStateException("CONFIG_RESTART_REQUIRES_EMPTY_SERVER");
            return reviewConfig().thenAcceptAsync(review->{if(!review.allows(id))throw new IllegalStateException("CONFIG_OTHER_PENDING");var row=review.entries().stream().filter(e->e.id().equals(id)).findFirst().orElseThrow();if(Set.of("IDENTITY_MISMATCH","EVIDENCE_MISSING").contains(row.problem()))throw new IllegalStateException("CONFIG_EVIDENCE_REVIEW");},owner)
                .thenCompose(v->writeConfig(plan,rollback,false)).thenCompose(v->store.prepareConfig(id,plan.name(),plan.before(),plan.after()))
                .thenRunAsync(()->{if(closed)throw new IllegalStateException("CONFIG_CLOSED");if(plan.restart()){restartRequired=true;maintenance=true;}},owner)
                .thenCompose(v->writeConfig(plan,rollback,true)).thenRunAsync(()->{try{if(!plan.restart())loadLive(plan.name());}catch(Exception e){throw new CompletionException(e);}},owner)
                .thenComposeAsync(v->jobs.configure(settings.jobs()),owner)
                .thenCompose(v->store.config(id,plan.name(),plan.before(),plan.after(),"PREPARED",rollback?"ROLLED_BACK":"COMMITTED"))
                .thenCompose(v->files.submit(()->{changes.mark(plan,rollback?"ROLLED_BACK":"COMMITTED");return (Void)null;}));
        },owner).thenCompose(v->reviewConfig()).thenAcceptAsync(review->settleConfiguration(restartRequired||!review.clear()),owner)
            .whenCompleteAsync((v,e)->{configBusy=false;if(e!=null&&!harmless(e))maintenance=true;metrics.record("config",System.nanoTime()-start,e!=null);},owner);
    }
    public CompletionStage<Void> archiveConfig(UUID id){if(!configIdle())return CompletableFuture.failedFuture(new IllegalStateException("CONFIG_BUSY"));configBusy=true;
        return archives.config(id).thenCompose(row->files.submit(()->{var plan=changes.plan(id);if(!plan.name().equals(row.value().name())||!plan.before().equals(row.value().before())||!plan.after().equals(row.value().after())||!changes.state(plan).equals(row.value().state()))throw new IllegalStateException("ARCHIVE_EVIDENCE_MISMATCH");return plan;}).thenCompose(plan->archives.config(row).thenCompose(v->files.submit(()->{changes.archive(plan);return (Void)null;}))))
            .thenCompose(v->reviewConfig()).thenAcceptAsync(review->settleConfiguration(restartRequired||!review.clear()),owner).whenCompleteAsync((v,e)->{configBusy=false;if(e!=null)maintenance=true;},owner);
    }
    public CompletionStage<Void> archiveJob(UUID id){if(!configIdle())return CompletableFuture.failedFuture(new IllegalStateException("PLATFORM_BUSY"));configBusy=true;return jobs.inspect(id).thenCompose(job->archives.job(job.orElseThrow())).thenComposeAsync(v->jobs.refresh(),owner).thenApply(v->(Void)null).whenCompleteAsync((v,e)->configBusy=false,owner);}
    public CompletionStage<Void> vaultResource(UUID id,boolean restore){if(!configIdle())return CompletableFuture.failedFuture(new IllegalStateException("PLATFORM_BUSY"));configBusy=true;
        return store.resets().thenCombine(store.reset(id),(rows,row)->Map.entry(rows,row)).thenCombine(archives.vault(id),(pair,vault)->Map.entry(pair,vault)).thenComposeAsync(input->{
            var pair=input.getKey();var row=pair.getValue();if(!row.phase().equals("RETIRED")||row.world()==null||Bukkit.getWorld(row.world())!=null||rpg.runtime.worlds().worlds().values().stream().anyMatch(w->w.getUID().equals(row.world()))||pair.getKey().stream().anyMatch(r->Set.of("ACTIVE","PREPARING","READY").contains(r.phase())&&(row.world().equals(r.world())||row.world().equals(r.oldWorld())))||jobs.held())throw new IllegalStateException("VAULT_WORLD_IN_USE");
            Path level=Bukkit.getServer().getLevelDirectory();var existing=input.getValue();
            return files.submit(()->{var vault=new ResourceVault(level);Path path=Files.exists(vault.source(row.key()),LinkOption.NOFOLLOW_LINKS)?vault.source(row.key()):vault.cold(id);if(!SurvivalWorlds.metadataUuid(path.resolve("data/paper/metadata.dat")).equals(row.world()))throw new IllegalStateException("VAULT_WORLD_IDENTITY");return vault.seal(path);})
                .thenCompose(seal->{if(restore){var v=existing.orElseThrow();if(!v.seal().equals(seal))throw new IllegalStateException("VAULT_CHANGED");return v.state().equals("STORED")?archives.transition(v,"RESTORING"):CompletableFuture.completedFuture(v);}return archives.prepare(row,seal).thenCompose(v->v.state().equals("RESTORED")?archives.transition(v,"PREPARED"):CompletableFuture.completedFuture(v));})
                .thenCompose(v->{String required=restore?"RESTORING":"PREPARED",done=restore?"RESTORED":"STORED";if(!Set.of(required,done).contains(v.state()))throw new IllegalStateException("VAULT_STATE");return files.submit(()->{new ResourceVault(level).move(v.key(),v.id(),v.seal(),restore);return (Void)null;}).thenCompose(x->v.state().equals(done)?CompletableFuture.completedFuture(v):archives.transition(v,done));});
        },owner).thenCompose(v->archives.vaults()).thenAcceptAsync(rows->{vaultPending=(int)rows.stream().filter(v->Set.of("PREPARED","RESTORING").contains(v.state())).count();settleConfiguration(restartRequired||!configReview.clear());},owner).whenCompleteAsync((v,e)->{configBusy=false;if(e!=null)maintenance=true;},owner);
    }
    public Map<String,Long> diagnostics(){return Map.ofEntries(Map.entry("enabled",1L),Map.entry("ready",gate().dispatch()?1L:0L),Map.entry("maintenance",maintenance?1L:0L),Map.entry("config_busy",configBusy?1L:0L),Map.entry("config_held",configReview.entries().stream().filter(ConfigurationReview.Entry::blocked).count()+(long)configReview.issues().size()),Map.entry("vault_held",(long)vaultPending),Map.entry("job_held",jobs.held()?1L:0L),Map.entry("io_pending",(long)files.pending()),Map.entry("sales",(long)sales.size()),Map.entry("generation",generation),Map.entry("reset_pending",(long)resources.pending().size()));}
    public List<String> status(){return List.of("준비="+ready()+" 유지보수="+maintenance+" 설정 세대="+generation,"설정 보류="+configReview.entries().stream().filter(ConfigurationReview.Entry::blocked).count()+" 증거 오류="+configReview.issues().size()+" 보관 보류="+vaultPending+" 파일 작업="+files.pending()+" 재시작 필요="+restartRequired,"강화="+settings.upgrade()+" 자동 판매="+settings.autosell()+" 처리중="+sales.size()+" 큐="+dirty.size(),"자원 세대="+resources.active()+" 보류="+resources.pending(),"예약 작업="+jobs.summary(),"효과 추적 계정="+rpg.aura.statLedger.playerCount()+" native 보류="+rpg.runtime.economy().journal.pending().size(),"지표="+metrics.snapshot(),"TPS="+Arrays.toString(Bukkit.getTPS())+" MSPT="+Bukkit.getAverageTickTime()+" heap="+(Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory()));}
    public CompletionStage<Void> drain(){return configBusy||files.pending()>0||resources.busy()||jobs.busy()||!sales.isEmpty()||!preferenceBusy.isEmpty()?CompletableFuture.failedFuture(new IllegalStateException("PLATFORM_BUSY")):CompletableFuture.completedFuture(null);}
    public void close(){closed=true;files.close();pulse.cancel();jobs.close();resources.close();menus.close();HandlerList.unregisterAll(this);dirty.clear();if(rpg.enchants!=null)rpg.enchants.deliveryObserver((a,b,c,d)->{});}
}
